<script setup>
import * as yup from 'yup'
import { i18nRender } from '@/locales'
import { useForm } from 'vee-validate'
import { updateKnowledge } from '@/services/knowledge'
import useToastService from '@/hooks/useToastService'

const toast = useToastService()

const props = defineProps({
  stepperData: {
    type: Object,
    default: () => {
      return {}
    }
  },
  data: {
    type: Object,
    default: () => {
      return {}
    }
  },
  isEdit: {
    type: Boolean,
    default: false
  }
})

const form = reactive({
  name: '',
  description: ''
})

const schema = yup.object({
  name: yup
    .string()
    .required(i18nRender('lang.noEmpty'))
    .max(60, i18nRender('kb.nameTip'))
    .matches(/^[a-zA-Z][a-zA-Z0-9_]{1,60}[a-zA-Z0-9]$/, i18nRender('kb.nameTip'))
    // .matches(/^[a-zA-Z0-9]+[a-zA-Z0-9_]*$/, i18nRender('kb.nameTip'))
    // .matches(/^[a-zA-Z0-9\u4e00-\u9fa5]+[a-zA-Z0-9\u4e00-\u9fa5_]*$/, i18nRender('kb.nameTip'))
    .label(i18nRender('kb.createKb'))
})

const { defineField, handleSubmit, errors } = useForm({
  validationSchema: schema
})

form.name = defineField('name')[0]

const emits = defineEmits(['hide', 'success'])

function close() {
  emits('hide')
}

const submit = handleSubmit(() => {
  updateKnowledge({
    id: props.data.id,
    description: form.description
  }).then(() => {
    toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.editSuccess'), life: 3000 })
    emits('success')
  })
})

const getFormData = handleSubmit(
  () => {
    return form
  },
  () => {
    return false
  }
)

onMounted(() => {
  if (Object.keys(props.stepperData).length > 0) {
    form.name = props.stepperData.name
    form.description = props.stepperData.description
  }
  if (props.isEdit) {
    form.name = props.data.name
    form.description = props.data.description
  }
})

defineExpose({
  getFormData
})
</script>
<template>
  <div class="form_item">
    <label for="username" class="text-slate-500 font-bold text-sm">{{ $t('kb.name') }}</label>
    <span v-if="isEdit" class="ml-3">{{ form.name }}</span>
    <div class="flex flex-col items-start justify-start mt-1" v-else>
      <InputText id="username" :invalid="!!errors.name" class="w-full" type="text" v-model="form.name" />
      <small class="my-1" :class="errors.name ? ['text-red-400'] : []">{{ $t('kb.nameTip') }}</small>
    </div>
  </div>
  <div class="form_item mt-3">
    <label for="description" class="text-slate-500 font-bold text-sm">{{ $t('kb.desc') }}</label>
    <div class="flex flex-col items-start justify-start mt-1">
      <Textarea id="description" class="w-full" v-model="form.description" autoResize rows="5" cols="30" maxlength="100" />
    </div>
  </div>
  <div class="flex items-center justify-end space-x-4 mt-4" v-if="isEdit">
    <Button :label="$t('lang.cancel')" severity="secondary" @click="close"></Button>
    <Button :label="$t('lang.confirm')" @click="submit"></Button>
  </div>
</template>
<style lang=""></style>
