<script setup>
import { getEmbedModels } from '@/services/knowledge'
import { ref } from 'vue'
const form = reactive({
  embed_model: '',

  chunk_size: 200,
  overlap_size: 20,
  distance_strategy: 'cosine',

  search_type: 'similarity',
  k: 5,
  score_threshold: 0.5,
  fetch_k: 20,
  lambda_mult: 0.5,
  prompt_template: '请根据检索到的背景信息，回答问题'
})

const searchType = reactive([
  {
    label: 'similarity',
    value: 'similarity'
  },
  {
    label: 'similarity_score_threshold',
    value: 'similarity_score_threshold'
  },
  {
    label: 'mmr',
    value: 'mmr'
  }
])

const distanceStrategy = reactive([
  {
    label: 'cosine',
    value: 'cosine'
  },
  {
    label: 'l2',
    value: 'l2'
  },
  {
    label: 'ip',
    value: 'ip'
  }
])

const modelList = ref([])
async function getModelList() {
  await getEmbedModels().then((res) => {
    const result = res.resData
    modelList.value = result.filter((item) => item.key === 'ollama' || item.key === 'siliconflow')
  })
}

const formatOptionLabel = (option) => {
  if (!option) return ''
  return `${option.cn_name} : ${option.name}`
}

function getSettingData() {
  const result = {
    global_param: {
      embed_model: form.embed_model
    },
    storage_param: {
      chunk_size: form.chunk_size,
      overlap_size: form.overlap_size,
      distance_strategy: form.distance_strategy
    },
    query_param: {
      search_type: form.search_type,
      k: form.k,
      score_threshold: form.score_threshold,
      fetch_k: form.fetch_k,
      lambda_mult: form.lambda_mult,
      prompt_template: form.prompt_template
    }
  }
  return new Promise((resolve) => {
    resolve(result)
  })
}

defineExpose({
  getSettingData
})

onMounted(() => {
  getModelList()
})
</script>
<template>
  <div>
    <div class="form_item">
      <label class="text-slate-500 font-bold text-sm">{{ $t('kb.embedModelPath') }}</label>
      <div class="flex justify-start items-center space-x-2">
        <Dropdown class="w-3/5" v-model="form.embed_model" :options="modelList" :optionLabel="formatOptionLabel" optionValue="local_path" />
      </div>
    </div>
    <Fieldset :legend="$t('kb.storageParams')">
      <div class="form_item">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.chunkSize') }}</label>
        <div class="flex justify-start items-center space-x-2">
          <Slider class="w-full" v-model="form.chunk_size" :min="50" :max="1024" />
          <InputNumber v-model="form.chunk_size" :min="50" :max="1024" :useGrouping="false" />
        </div>
      </div>
      <div class="form_item">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.overlapSize') }}</label>
        <div class="flex justify-start items-center space-x-2">
          <Slider class="w-full" v-model="form.overlap_size" :min="0" :max="100" />
          <InputNumber v-model="form.overlap_size" :min="0" :max="100" :useGrouping="false" />
        </div>
      </div>
      <div class="form_item">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.distanceStrategy') }}</label>
        <Dropdown class="w-full" v-model="form.distance_strategy" :options="distanceStrategy" optionLabel="label" optionValue="value" />
      </div>
    </Fieldset>
    <Fieldset :legend="$t('kb.searchParams')">
      <div class="form_item">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.textCount') }}</label>
        <div class="flex justify-start items-center space-x-2">
          <Slider class="w-full" v-model="form.k" :min="1" :max="20" />
          <InputNumber v-model="form.k" :min="1" :max="20" :useGrouping="false" />
        </div>
      </div>
      <div class="form_item">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.searchType') }}</label>
        <Dropdown class="w-full" v-model="form.search_type" :options="searchType" optionLabel="label" optionValue="value" />
      </div>
      <div class="form_item" v-if="form.search_type === 'similarity_score_threshold'">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.scoreThreshold') }}</label>
        <div class="flex justify-start items-center space-x-2">
          <Slider class="w-full" v-model="form.score_threshold" :min="0" :max="1" :step="0.1" />
          <InputNumber v-model="form.score_threshold" :min="0" :max="1" :step="0.1" :useGrouping="false" />
        </div>
      </div>
      <div class="form_item" v-if="form.search_type === 'mmr'">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.fetchK') }}</label>
        <div class="flex justify-start items-center space-x-2">
          <Slider class="w-full" v-model="form.fetch_k" :min="1" :max="50" />
          <InputNumber v-model="form.fetch_k" :min="1" :max="50" :useGrouping="false" />
        </div>
      </div>
      <div class="form_item" v-if="form.search_type === 'mmr'">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.lambdaMult') }}</label>
        <div class="flex justify-start items-center space-x-2">
          <Slider class="w-full" v-model="form.lambda_mult" :min="0" :max="1" :step="0.1" />
          <InputNumber v-model="form.lambda_mult" :min="0" :max="1" :step="0.1" :useGrouping="false" />
        </div>
      </div>
      <div class="form_item">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.propmtTemplate') }}</label>
        <Textarea class="w-full" v-model="form.prompt_template" rows="5" cols="30" :maxlength="300" />
      </div>
    </Fieldset>
  </div>
</template>
<style scoped>
.form_item {
  @apply mb-1;
}
</style>
