<script setup>
import Stepper from 'primevue/stepper'
import StepperPanel from 'primevue/stepperpanel'
import KnowledgeBasic from './KnowledgeBasic.vue'
import UploadFile from './UploadFile.vue'
import KnowledgeSetting from './KnowledgeSetting.vue'
import { createKnowledge } from '@/services/knowledge'
import useToastService from '@/hooks/useToastService'
import { i18nRender } from '@/locales'
import Markdown from '@/views/chat/components/Markdown.vue'

const toast = useToastService()
const activeStep = ref(0)
const knowledgeBasicRef = ref()
const uploadFileRef = ref()
const knowledgeSettingRef = ref()
const basicFormData = ref({})
const selectedFiles = ref([])
const showhasnoflag = ref(false)
const needaddembed = `
请设置 ⚙️<strong>【嵌入模型】</strong>。
`
async function handleNext(callback) {
  if (activeStep.value === 0) {
    knowledgeBasicRef.value.getFormData().then((result) => {
      if (result) {
        basicFormData.value = Object.assign({}, result)
        callback()
      }
    })
  } else if (activeStep.value === 1) {
    await uploadFileRef.value.getSelectedFiles().then((result) => {
      selectedFiles.value = result
    })
    if (selectedFiles.value.length > 0) {
      callback()
    } else {
      toast.add({ severity: 'error', summary: i18nRender('kb.error'), detail: i18nRender('kb.selectFileTip'), life: 3000 })
    }
  }
}

const emits = defineEmits(['success'])
const loading = ref(false)
async function handleFinish() {
  const settingData = await knowledgeSettingRef.value.getSettingData()
  if (settingData.global_param.embed_model === '') {
    showhasnoflag.value = true
    return
  } else {
    const formData = new FormData()
    selectedFiles.value.forEach((file) => {
      formData.append('files', file)
    })
    formData.append('name', basicFormData.value.name)
    formData.append('description', basicFormData.value.description)
    formData.append('knowledge_setting', JSON.stringify(settingData))
    loading.value = true
    createKnowledge(formData)
      .then(() => {
        toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.createSuccess'), life: 3000 })
        emits('success')
      })
      .finally(() => {
        loading.value = false
      })
  }
}
</script>
<template>
  <Stepper linear v-model:activeStep="activeStep">
    <StepperPanel :header="$t('kb.basicInfo')">
      <template #content="{ nextCallback }">
        <div class="flex flex-col">
          <KnowledgeBasic ref="knowledgeBasicRef" :stepperData="basicFormData" />
        </div>
        <div class="flex pt-4 justify-end">
          <Button :label="$t('kb.next')" icon="pi pi-arrow-right" iconPos="right" @click="handleNext(nextCallback)" />
        </div>
      </template>
    </StepperPanel>
    <StepperPanel :header="$t('kb.uploadFile')">
      <template #content="{ prevCallback, nextCallback }">
        <div class="flex flex-col">
          <UploadFile ref="uploadFileRef" />
        </div>
        <div class="flex pt-4 justify-between">
          <Button :label="$t('kb.previous')" severity="secondary" icon="pi pi-arrow-left" @click="prevCallback" />
          <Button :label="$t('kb.next')" icon="pi pi-arrow-right" iconPos="right" @click="handleNext(nextCallback)" />
        </div>
      </template>
    </StepperPanel>
    <StepperPanel :header="$t('kb.kbSetting')">
      <template #content="{ prevCallback }">
        <div class="flex flex-col">
          <KnowledgeSetting ref="knowledgeSettingRef" />
        </div>
        <div class="flex pt-4 justify-between">
          <Button :label="$t('kb.previous')" severity="secondary" icon="pi pi-arrow-left" @click="prevCallback" :disabled="loading" />
          <Button :label="$t('kb.create')" @click="handleFinish" :disabled="loading" />
        </div>
        <Dialog v-model:visible="showhasnoflag" header="检测到未添加【嵌入模型】" :style="{ width: '800px' }" :model="true">
          <div class="content-box">
            <Markdown :content="needaddembed"></Markdown>
          </div>
        </Dialog>
      </template>
    </StepperPanel>
  </Stepper>
</template>
<style lang=""></style>
