<script setup>
import { i18nRender } from '@/locales'
import { updateKnowledge, getKnowledgeSetting } from '@/services/knowledge'
import useToastService from '@/hooks/useToastService'

const toast = useToastService()
const loading = ref(false)
const props = defineProps({
  data: {
    type: Object,
    default: () => {
      return {}
    }
  }
})

const searchType = reactive([
  {
    label: 'similarity',
    value: 'similarity'
  },
  {
    label: 'similarity_score_threshold',
    value: 'similarity_score_threshold'
  },
  {
    label: 'mmr',
    value: 'mmr'
  }
])

const form = reactive({
  name: '',
  description: ''
})

const settingForm = reactive({
  search_type: 'similarity',
  k: 4,
  score_threshold: 0.5,
  fetch_k: 20,
  lambda_mult: 0.5,
  prompt_template: ''
})

const emits = defineEmits(['hide', 'success'])

function close() {
  emits('hide')
}

function submit() {
  loading.value = true
  updateKnowledge({
    id: props.data.id,
    description: form.description,
    user: [],
    knowledge_setting: JSON.stringify(settingForm)
  })
    .then(() => {
      toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.editSuccess'), life: 3000 })
      emits('success', settingForm)
    })
    .finally(() => {
      loading.value = false
    })
}

function initFormData() {
  form.name = props.data.name
  form.description = props.data.description
  loading.value = true
  getKnowledgeSetting(props.data.id)
    .then((res) => {
      const result = res.resData
      settingForm.search_type = result.search_type
      settingForm.k = result.k
      settingForm.score_threshold = result.score_threshold
      settingForm.fetch_k = result.fetch_k
      settingForm.lambda_mult = result.lambda_mult
      settingForm.prompt_template = result.prompt_template
    })
    .finally(() => {
      loading.value = false
    })
}

onMounted(() => {
  initFormData()
})
</script>
<template>
  <div class="form_item">
    <label for="username" class="text-slate-500 font-bold text-sm">{{ $t('kb.name') }}</label>
    <span class="ml-3">{{ form.name }}</span>
  </div>
  <div class="form_item mt-3">
    <label for="description" class="text-slate-500 font-bold text-sm">{{ $t('kb.desc') }}</label>
    <div class="flex flex-col items-start justify-start mt-1">
      <Textarea id="description" class="w-full" v-model="form.description" autoResize rows="5" cols="30" maxlength="100" />
    </div>
  </div>

  <div class="form_item">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.textCount') }}</label>
    <div class="flex justify-start items-center space-x-2">
      <Slider class="w-full" v-model="settingForm.k" :min="1" :max="20" />
      <InputNumber v-model="settingForm.k" :min="1" :max="20" :useGrouping="false" />
    </div>
  </div>
  <div class="form_item">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.searchType') }}</label>
    <Dropdown class="w-full" v-model="settingForm.search_type" :options="searchType" optionLabel="label" optionValue="value" />
  </div>
  <div class="form_item" v-if="settingForm.search_type === 'similarity_score_threshold'">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.scoreThreshold') }}</label>
    <div class="flex justify-start items-center space-x-2">
      <Slider class="w-full" v-model="settingForm.score_threshold" :min="0" :max="1" :step="0.1" />
      <InputNumber v-model="settingForm.score_threshold" :min="0" :max="1" :step="0.1" :useGrouping="false" />
    </div>
  </div>
  <div class="form_item" v-if="settingForm.search_type === 'mmr'">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.fetchK') }}</label>
    <div class="flex justify-start items-center space-x-2">
      <Slider class="w-full" v-model="settingForm.fetch_k" :min="1" :max="50" />
      <InputNumber v-model="settingForm.fetch_k" :min="1" :max="50" :useGrouping="false" />
    </div>
  </div>
  <div class="form_item" v-if="settingForm.search_type === 'mmr'">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.lambdaMult') }}</label>
    <div class="flex justify-start items-center space-x-2">
      <Slider class="w-full" v-model="settingForm.lambda_mult" :min="0" :max="1" :step="0.1" />
      <InputNumber v-model="settingForm.lambda_mult" :min="0" :max="1" :step="0.1" :useGrouping="false" />
    </div>
  </div>
  <div class="form_item">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.propmtTemplate') }}</label>
    <Textarea class="w-full" v-model="settingForm.prompt_template" rows="5" cols="30" :maxlength="300" />
  </div>
  <div class="flex items-center justify-end space-x-4 mt-4">
    <Button :label="$t('lang.cancel')" severity="secondary" @click="close"></Button>
    <Button :label="$t('lang.confirm')" @click="submit" :loading="loading"></Button>
  </div>
</template>
<style scoped>
.form_item {
  @apply mb-2;
}
</style>
