<script setup>
import * as yup from 'yup'
import { i18nRender } from '@/locales'
import { useForm } from 'vee-validate'
import { getDBConfig, updateDBConfig, getEmbedModels } from '@/services/knowledge'
import useToastService from '@/hooks/useToastService'

const toast = useToastService()

const form = reactive({
  chromadb_persist_path: '',
  embed_model: ''
})

const schema = yup.object({
  chromadb_persist_path: yup.string().required(i18nRender('lang.noEmpty')),
  embed_model: yup.string().required(i18nRender('lang.noEmpty'))
})

const { defineField, handleSubmit, errors } = useForm({
  validationSchema: schema
})

form.chromadb_persist_path = defineField('chromadb_persist_path')[0]
form.embed_model = defineField('embed_model')[0]

const emits = defineEmits(['hide', 'success'])

function close() {
  emits('hide')
}

function checkDBConfig() {
  // chromadb, milvus
  getDBConfig('chromadb').then((res) => {
    const result = res.resData
    form.chromadb_persist_path = result.chromadb_persist_path
    form.embed_model = result.embed_model
  })
}

const loading = ref(false)
const modelList = ref([])
async function getModelList() {
  loading.value = true
  await getEmbedModels().then((res) => {
    const result = res.resData
    modelList.value = result.filter((item) => item.key === 'ollama' || item.key === 'siliconflow')
  })
  await checkDBConfig()
  loading.value = false
}

const formatOptionLabel = (option) => {
  if (!option) return ''
  return `${option.cn_name} : ${option.name}`
}

const submit = handleSubmit(() => {
  updateDBConfig({
    name: 'chromadb',
    chromadb_persist_path: form.chromadb_persist_path,
    embed_model: form.embed_model
  }).then(() => {
    toast.add({ severity: 'success', summary: i18nRender('kb.success'), detail: i18nRender('kb.editSuccess'), life: 3000 })
    emits('success')
  })
})
onMounted(() => {
  getModelList()
})
</script>

<template>
  <div class="form_item">
    <label class="text-slate-500 font-bold text-sm">{{ $t('kb.chromaPath') }}</label>
    <div class="flex flex-col items-start justify-start mt-1">
      <InputText :invalid="!!errors.chromadb_persist_path" class="w-full" type="text" v-model="form.chromadb_persist_path" />
      <small class="my-1 text-red-400" v-if="errors.chromadb_persist_path">{{ $t('lang.noEmpty') }}</small>
    </div>
  </div>
  <div class="form_item mt-3">
    <label for="description" class="text-slate-500 font-bold text-sm">{{ $t('kb.embedModelPath') }}</label>
    <div class="flex flex-col items-start justify-start mt-1">
      <Dropdown
        class="w-3/5"
        v-model="form.embed_model"
        :invalid="!!errors.embed_model"
        :options="modelList"
        :optionLabel="formatOptionLabel"
        optionValue="local_path"
      />
      <small class="my-1 text-red-400" v-if="errors.embed_model">{{ $t('lang.noEmpty') }}</small>
    </div>
  </div>
  <div class="flex items-center justify-end space-x-4 mt-4">
    <Button :label="$t('lang.cancel')" severity="secondary" @click="close"></Button>
    <Button :label="$t('lang.confirm')" @click="submit" :disabled="loading"></Button>
  </div>
</template>
<style lang=""></style>
